typedef struct {
    // Byte 0: flags and priority
    uint8_t flags;
    // Bits 0-4: priority (0-31, higher = more important)
    // Bits 5-7: track_count - 1 (for multi-track sounds, 0x00-0x181)
    // Bit 7:    unique_instance flag (for single-track sounds, 0x200+)

    // Byte 1: bank and channel hint
    uint8_t bank_channel;
    // Bits 0-3: bank_id (which sound bank to use)
    // Bits 4-7: preferred_channel (0 = auto-assign)

    // Bytes 2-3: padding/reserved
    uint8_t reserved[2];

    // Bytes 4-7: pointer to track data
    void *track_data;

} SoundEffectEntry;

